/*
 * A284808  Fixed points of the transform A284807.
 * https://oeis.org/A284808
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th fixed point of the transform A284807, i.e., the
 *            n-th base‑8 number of even length that satisfies for each
 *            position i: digit(i) + digit(2k-1-i) = 7. The sequence is
 *            generated by enumerating all possible digit pairs
 *            (b_0,…,b_{k-1}) with b_0≠7 in lexical order: b_0 decreasing from
 *            6...
 * Range:     u8 n <= 7, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    if (n < 1) return 0;   /* undefined behaviour below offset */

    /* Determine the block (length 2k).  Total numbers up to length 2k is 8^k-1. */
    unsigned __int128 pow8 = 1;   /* 8^0 */
    int k = 0;                    /* k >= 1, because n >= 1 */
    while (pow8 <= n) {          /* find smallest k with 8^k > n */
        pow8 *= 8;
        k++;
    }

    idx_t pow8_prev = (idx_t)(pow8 / 8);   /* 8^(k-1) */
    idx_t offset   = n - pow8_prev;        /* 0‑based index within current block */

    /* Extract the mixed radix digits c[0]..c[k-1] from offset.
       c[0] ∈ [0,6], c[1..k-1] ∈ [0,7].                     */
    uint8_t c[64];
    idx_t tmp = offset;
    for (int i = k - 1; i >= 0; i--) {
        c[i] = (uint8_t)(tmp % 8);
        tmp /= 8;
    }

    /* Convert to the original digits b[0]..b[k-1]:
          b0 = 6 - c0  (0…6);
          bi = 7 - ci  (i≥1).                            */
    uint8_t b[64];
    b[0] = 6 - c[0];
    for (int i = 1; i < k; i++) {
        b[i] = 7 - c[i];
    }

    /* Build the base‑8 number: [7-b0 … 7-b_{k-1} | b_{k-1} … b0]. */
    seq_t val = 0;
    for (int i = 0; i < k; i++) {
        val = val * 8 + (seq_t)(7 - b[i]);   /* most significant side */
    }
    for (int i = k - 1; i >= 0; i--) {
        val = val * 8 + (seq_t)b[i];         /* least significant side */
    }

    return val;
}
